// NODE: the fundamental building block
class ListNode {
    constructor(val, next = null) {
        this.val  = val;
        this.next = next;
    }
}

// LINKED LIST: wrapper managing the head pointer
class LinkedList {
    constructor() { this.head = null; this.size = 0; }

    // Prepend: insert at head — O(1)
    prepend(val) {
        this.head = new ListNode(val, this.head);
        this.size++;
    }

    // Append: insert at tail — O(n) traverse to tail
    append(val) {
        const node = new ListNode(val);
        if (!this.head) { this.head = node; }
        else {
            let curr = this.head;
            while (curr.next) curr = curr.next; // walk to tail
            curr.next = node;
        }
        this.size++;
    }

    // Search: find first node with value — O(n)
    find(val) {
        let curr = this.head;
        while (curr) {
            if (curr.val === val) return curr;
            curr = curr.next;
        }
        return null;
    }

    // toArray: snapshot for inspection — O(n)
    toArray() {
        const result = [];
        let curr = this.head;
        while (curr) { result.push(curr.val); curr = curr.next; }
        return result;
    }
}

const list = new LinkedList();
list.append(1); list.append(2); list.append(3);
list.prepend(0);
console.log(list.toArray()); // [0, 1, 2, 3]
console.log(list.size);      // 4

