// INSERT AFTER A GIVEN NODE — O(1)
function insertAfter(prev, val) {
    const newNode = new ListNode(val, prev.next); // newNode -> prev's old next
    prev.next = newNode;                           // prev -> newNode
}

// DELETE NODE AFTER A GIVEN PREDECESSOR — O(1)
function deleteAfter(prev) {
    if (!prev.next) return; // nothing to delete
    prev.next = prev.next.next; // skip the node after prev
    // The skipped node becomes garbage-collected
}

// DUMMY HEAD PATTERN — eliminates head-deletion special case
function removeAllOccurrences(head, val) {
    const dummy = new ListNode(0, head); // dummy precedes the real head
    let prev = dummy;

    while (prev.next) {
        if (prev.next.val === val) {
            prev.next = prev.next.next; // delete: don't advance prev
        } else {
            prev = prev.next;           // no delete: advance prev
        }
    }
    return dummy.next; // real head (may have changed if original head was deleted)
}

// TRACE on [1,2,6,3,4,5,6], val=6:
