// DELETE MIDDLE NODE given only the node itself (not predecessor)
// Classic trick: copy successor's value and delete the successor
function deleteNode(node) {
    // Assumes node is not the tail
    node.val  = node.next.val;  // copy successor's value
    node.next = node.next.next; // skip successor
}

