// ITERATIVE REVERSAL — O(n) time, O(1) space
function reverseList(head) {
    let prev = null;
    let curr = head;
    while (curr) {
        const next = curr.next; // save next before overwriting
        curr.next = prev;       // reverse the pointer
        prev = curr;            // advance prev
        curr = next;            // advance curr
    }
    return prev; // prev is now the new head
}
// 1->2->3->4->5->null
// Step 1: prev=null, curr=1, next=2: 1->null. prev=1, curr=2
// Step 2: prev=1,    curr=2, next=3: 2->1.    prev=2, curr=3
// Step 3: prev=2,    curr=3, next=4: 3->2.    prev=3, curr=4
// Step 4: prev=3,    curr=4, next=5: 4->3.    prev=4, curr=5
// Step 5: prev=4,    curr=5, next=null: 5->4. prev=5, curr=null
// Loop ends. Return prev=5. List: 5->4->3->2->1->null

// RECURSIVE REVERSAL — O(n) time, O(n) space (call stack)
function reverseListRecursive(head) {
    if (!head || !head.next) return head; // base: 0 or 1 node
    const newHead = reverseListRecursive(head.next); // trust: reverses head.next..tail
    // At this point: head.next is the last node of the reversed tail
    head.next.next = head; // make the old second node point back to head
    head.next = null;      // head is now the new tail
    return newHead;        // new head (original tail)
}

// REVERSE SUBLIST [left, right] — 1-indexed
function reverseBetween(head, left, right) {
    const dummy = new ListNode(0, head);
    let prev = dummy;
    // Step 1: walk to node before left
    for (let i = 1; i < left; i++) prev = prev.next;
    // Step 2: reverse the sublist of length (right - left + 1)
    let curr = prev.next;
    let tail = null;
    for (let i = 0; i < right - left + 1; i++) {
        const next = curr.next;
        curr.next = tail;
        tail = curr;
        curr = next;
    }
    // Step 3: reconnect
    prev.next.next = curr; // original left node (now sublist tail) -> node after right
    prev.next = tail;      // node before left -> new sublist head (original right node)
    return dummy.next;
}

