// DOUBLY LINKED LIST with sentinel head and tail
class DLLNode {
    constructor(val, prev = null, next = null) {
        this.val  = val;
        this.prev = prev;
        this.next = next;
    }
}

class DoublyLinkedList {
    constructor() {
        // Sentinel nodes: never removed, always present
        this.head = new DLLNode(0); // dummy head
        this.tail = new DLLNode(0); // dummy tail
        this.head.next = this.tail;
        this.tail.prev = this.head;
        this.size = 0;
    }

    // Insert node between prev and next — O(1), 4 pointer updates
    _insertBetween(node, prevNode, nextNode) {
        node.prev = prevNode;
        node.next = nextNode;
        prevNode.next = node;
        nextNode.prev = node;
        this.size++;
    }

    // Remove a given node — O(1), no predecessor search needed
    _remove(node) {
        node.prev.next = node.next; // predecessor skips node
        node.next.prev = node.prev; // successor skips node backward
        node.prev = null;           // help GC
        node.next = null;
        this.size--;
    }

    // Add to front (after dummy head) — O(1)
    addToFront(val) {
        const node = new DLLNode(val);
        this._insertBetween(node, this.head, this.head.next);
        return node; // return reference for O(1) access later
    }

    // Remove from back (before dummy tail) — O(1)
    removeFromBack() {
        if (this.size === 0) return null;
        const node = this.tail.prev;
        this._remove(node);
        return node.val;
    }

    toArray() {
        const result = [];
        let curr = this.head.next;
        while (curr !== this.tail) { result.push(curr.val); curr = curr.next; }
        return result;
    }
}

const dll = new DoublyLinkedList();
const n1 = dll.addToFront(1);
const n2 = dll.addToFront(2);
const n3 = dll.addToFront(3);
console.log(dll.toArray());  // [3, 2, 1]
dll._remove(n2);              // delete middle node directly — O(1)
console.log(dll.toArray());  // [3, 1]
console.log(dll.removeFromBack()); // 1
console.log(dll.toArray());  // [3]

