class DLLNode {
  constructor(val, prev = null, next = null) { this.val = val; this.prev = prev; this.next = next; }
}

class DoublyLinkedList {
  constructor() {
    this.head = new DLLNode(0);
    this.tail = new DLLNode(0);
    this.head.next = this.tail;
    this.tail.prev = this.head;
    this.size = 0;
  }

  _insertBetween(node, prevNode, nextNode) {
    node.prev = prevNode;
    node.next = nextNode;
    prevNode.next = node;
    nextNode.prev = node;
    this.size++;
  }

  _remove(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
    node.prev = null;
    node.next = null;
    this.size--;
  }

  addToFront(val) {
    const node = new DLLNode(val);
    this._insertBetween(node, this.head, this.head.next);
    return node;
  }

  addToBack(val) {
    const node = new DLLNode(val);
    this._insertBetween(node, this.tail.prev, this.tail);
    return node;
  }

  removeFromFront() {
    if (this.size === 0) return null;
    const node = this.head.next;
    this._remove(node);
    return node.val;
  }

  removeFromBack() {
    if (this.size === 0) return null;
    const node = this.tail.prev;
    this._remove(node);
    return node.val;
  }

  toArray() {
    const r = []; let c = this.head.next;
    while (c !== this.tail) { r.push(c.val); c = c.next; }
    return r;
  }
}

