// FIND MIDDLE OF LINKED LIST
function findMiddle(head) {
    let slow = head, fast = head;
    // Stop when fast.next is null (odd) or fast.next.next is null (even)
    while (fast && fast.next) {
        slow = slow.next;       // 1 step
        fast = fast.next.next;  // 2 steps
    }
    return slow; // slow is at the middle
}
// [1,2,3,4,5]: slow stops at 3 (middle of 5 nodes)
// [1,2,3,4]:   slow stops at 2 (first of two middles)

// PALINDROME LINKED LIST — O(n) time, O(1) space
function isPalindrome(head) {
    // Step 1: find middle
    let slow = head, fast = head;
    while (fast && fast.next) { slow = slow.next; fast = fast.next.next; }

    // Step 2: reverse second half starting from slow
    let prev = null, curr = slow;
    while (curr) {
        const next = curr.next;
        curr.next = prev;
        prev = curr;
        curr = next;
    }
    // prev is now the head of the reversed second half

    // Step 3: compare first half (head) with reversed second half (prev)
    let left = head, right = prev;
    while (right) {
        if (left.val !== right.val) return false;
        left = left.next;
        right = right.next;
    }
    return true;
}
// [1,2,2,1]: middle=2(index 2), reverse [2,1], compare [1,2] vs [1,2] -> true
// [1,2,3,2,1]: middle=3, reverse [2,1], compare [1,2,3] vs [1,2] -> true

// REORDER LIST: L0->L1->...->Ln becomes L0->Ln->L1->Ln-1->...
function reorderList(head) {
    if (!head || !head.next) return;
    // Step 1: find middle
    let slow = head, fast = head;
    while (fast.next && fast.next.next) { slow = slow.next; fast = fast.next.next; }
    // Step 2: reverse second half
    let prev = null, curr = slow.next;
    slow.next = null; // cut list in half
    while (curr) { const next = curr.next; curr.next = prev; prev = curr; curr = next; }
    // Step 3: interleave
    let first = head, second = prev;
    while (second) {
        const tmp1 = first.next, tmp2 = second.next;
        first.next = second; second.next = tmp1;
        first = tmp1; second = tmp2;
    }
}

