// PHASE 1: DETECT CYCLE — O(n) time, O(1) space
function hasCycle(head) {
    let slow = head, fast = head;
    while (fast && fast.next) {
        slow = slow.next;
        fast = fast.next.next;
        if (slow === fast) return true; // cycle detected: pointers meet
    }
    return false; // fast reached end: no cycle
}

// DETECT CYCLE AND FIND CYCLE START
function detectCycle(head) {
    let slow = head, fast = head;

    // Phase 1: find meeting point inside cycle
    while (fast && fast.next) {
        slow = slow.next;
        fast = fast.next.next;
        if (slow === fast) break; // meeting point found
    }
    // If no cycle:
    if (!fast || !fast.next) return null;

    // Phase 2: find cycle start
    // Reset one pointer to head, keep other at meeting point
    // Both move 1 step at a time — they meet at cycle start
    slow = head;
    while (slow !== fast) {
        slow = slow.next;
        fast = fast.next; // only 1 step now
    }
    return slow; // cycle start node
}

// PROOF of Phase 2:
// Let F = distance from head to cycle start
// Let C = cycle length
// Let k = distance from cycle start to meeting point
// When they meet: slow traveled F+k, fast traveled F+k+n*C (n full laps extra)
// Since fast = 2 * slow: 2(F+k) = F+k+n*C -> F+k = n*C -> F = n*C - k
// After reset: slow travels F from head, fast travels F from meeting point
// fast travels F = n*C - k from meeting point, which is (n*C - k + k) = n*C
// steps around the cycle from cycle start = 0 steps past cycle start
// Both arrive at cycle start simultaneously

// FIND CYCLE LENGTH: count steps from meeting point back to itself
function cycleLength(head) {
    let slow = head, fast = head;
    while (fast && fast.next) {
        slow = slow.next; fast = fast.next.next;
        if (slow === fast) {
            let length = 1, curr = slow.next;
            while (curr !== slow) { length++; curr = curr.next; }
            return length;
        }
    }
    return 0; // no cycle
}

