// MERGE TWO SORTED LISTS — O(n+m) time, O(1) space
function mergeTwoLists(list1, list2) {
    const dummy = new ListNode(0);
    let curr = dummy;

    while (list1 && list2) {
        if (list1.val <= list2.val) {
            curr.next = list1;
            list1 = list1.next;
        } else {
            curr.next = list2;
            list2 = list2.next;
        }
        curr = curr.next;
    }
    // Attach remaining nodes (already sorted, O(1) pointer update)
    curr.next = list1 || list2;
    return dummy.next;
}

// MERGE K SORTED LISTS — divide and conquer O(N log k)
function mergeKLists(lists) {
    if (!lists || lists.length === 0) return null;
    return mergeRange(lists, 0, lists.length - 1);
}
function mergeRange(lists, lo, hi) {
    if (lo === hi) return lists[lo];          // base: single list
    const mid = lo + Math.floor((hi - lo) / 2);
    const left  = mergeRange(lists, lo, mid);     // merge left half
    const right = mergeRange(lists, mid + 1, hi); // merge right half
    return mergeTwoLists(left, right);             // merge results
}
// At each level: total nodes N, O(N) merge work
// log k levels (halving k lists each level)
// Total: O(N log k)

// SORT A LINKED LIST — merge sort O(n log n) time, O(log n) space
function sortList(head) {
    if (!head || !head.next) return head; // base case
    // Find middle
    let slow = head, fast = head.next; // fast starts at head.next for even-length split
    while (fast && fast.next) { slow = slow.next; fast = fast.next.next; }
    const mid = slow.next;
    slow.next = null;             // cut list in half
    const left  = sortList(head); // sort first half
    const right = sortList(mid);  // sort second half
    return mergeTwoLists(left, right);
}

