  return mergeRange(lists, 0, lists.length - 1);
}
function mergeRange(lists, lo, hi) {
  if (lo === hi) return lists[lo];
  const mid = lo + Math.floor((hi - lo) / 2);
  const left = mergeRange(lists, lo, mid);
  const right = mergeRange(lists, mid + 1, hi);
  return mergeTwoListsImpl(left, right);
}

function sortListImpl(head) {
  if (!head || !head.next) return head;
  let slow = head, fast = head.next;
  while (fast && fast.next) { slow = slow.next; fast = fast.next.next; }
  const mid = slow.next;
  slow.next = null;
  const left = sortListImpl(head);
  const right = sortListImpl(mid);
  return mergeTwoListsImpl(left, right);
}

