function removeNthFromEnd(head, n) {
    const dummy = new ListNode(0, head);
    let lead  = dummy;
    let trail = dummy;

    // Advance lead n+1 steps
    for (let i = 0; i <= n; i++) { // i <= n means n+1 iterations
        lead = lead.next;
    }

    // Move both until lead is null
    while (lead) {
        lead  = lead.next;
        trail = trail.next;
    }

    // trail is now at the predecessor of the nth node from end
    trail.next = trail.next.next; // remove target node
    return dummy.next;
}

