function findKthFromEnd(head, k) {
  let lead = head, trail = head;
  for (let i = 0; i < k; i++) {
    if (!lead) return -1;
    lead = lead.next;
  }
  while (lead) { lead = lead.next; trail = trail.next; }
  return trail.val;
}

