class LRUNode {
    constructor(key, val) {
        this.key  = key;  // store key for eviction from map
        this.val  = val;
        this.prev = null;
        this.next = null;
    }
}

class LRUCache {
    constructor(capacity) {
        this.capacity = capacity;
        this.map = new Map(); // key -> LRUNode
        // Sentinel doubly linked list: head=MRU end, tail=LRU end
        this.head = new LRUNode(0, 0); // dummy MRU sentinel
        this.tail = new LRUNode(0, 0); // dummy LRU sentinel
        this.head.next = this.tail;
        this.tail.prev = this.head;
    }

    // Insert node just after dummy head (MRU position)
    _insertFront(node) {
        node.next = this.head.next;
        node.prev = this.head;
        this.head.next.prev = node;
        this.head.next = node;
    }

    // Remove any node from the DLL — O(1) due to prev pointer
    _remove(node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    get(key) {
        if (!this.map.has(key)) return -1; // cache miss
        const node = this.map.get(key);    // O(1) lookup
        this._remove(node);                // O(1) remove from current position
        this._insertFront(node);           // O(1) move to MRU front
        return node.val;
    }

    put(key, val) {
        if (this.map.has(key)) {
            const node = this.map.get(key);
            node.val = val;
            this._remove(node);
            this._insertFront(node);       // update: move to front
        } else {
            if (this.map.size === this.capacity) {
                // Evict LRU: node just before dummy tail
                const lru = this.tail.prev;
                this._remove(lru);
                this.map.delete(lru.key);  // remove from map using stored key
            }
            const node = new LRUNode(key, val);
            this._insertFront(node);
            this.map.set(key, node);       // add to map
        }
    }
}

// TEST
const cache = new LRUCache(2);
cache.put(1, 1); // cache: {1=1}
cache.put(2, 2); // cache: {1=1, 2=2}
console.log(cache.get(1)); // 1 — moves 1 to front
cache.put(3, 3); // evicts 2 (LRU), cache: {1=1, 3=3}
console.log(cache.get(2)); // -1 — 2 was evicted
cache.put(4, 4); // evicts 1, cache: {3=3, 4=4}
console.log(cache.get(1)); // -1
console.log(cache.get(3)); // 3
console.log(cache.get(4)); // 4

