class ListNode {
  constructor(val, next = null) { this.val = val; this.next = next; }
}
function fromArr(arr) {
  if (!arr.length) return null;
  const h = new ListNode(arr[0]); let c = h;
  for (let i = 1; i < arr.length; i++) { c.next = new ListNode(arr[i]); c = c.next; }
  return h;
}
function toArr(head) { const r=[]; let c=head; while(c){r.push(c.val);c=c.next;} return r; }

function classifyLinkedListTechnique(signals) {
  const s = new Set(signals);
  if (s.has('reverse') || s.has('reorder')) return 'Pointer Manipulation';
  if (s.has('middle') || s.has('palindrome')) return 'Fast-Slow Pointer';
  if (s.has('cycle')) return "Floyd's Cycle Detection";
  if (s.has('kth_from_end') || s.has('remove_nth')) return 'Pointer Spacing';
  if (s.has('o1_get_put') || s.has('lru')) return 'DLL + Hash Map';
  return 'Unknown';
}

function solveReverse(head) {
  let prev = null, curr = head;
  while (curr) { const next = curr.next; curr.next = prev; prev = curr; curr = next; }
  return prev;
}

function solvePalindrome(head) {
  let slow = head, fast = head;
  while (fast && fast.next) { slow = slow.next; fast = fast.next.next; }
  let prev = null, curr = slow;
  while (curr) { const next = curr.next; curr.next = prev; prev = curr; curr = next; }
  let left = head, right = prev;
  while (right) { if (left.val !== right.val) return false; left = left.next; right = right.next; }
  return true;
}

function solveRemoveNth(head, n) {
  const dummy = new ListNode(0, head);
  let lead = dummy, trail = dummy;
  for (let i = 0; i <= n; i++) lead = lead.next;
  while (lead) { lead = lead.next; trail = trail.next; }
  trail.next = trail.next.next;
  return dummy.next;
}

function moduleCapabilitySummary() {
  return {
    pointerManipulation: toArr(solveReverse(fromArr([1,2]))).join(',') === '2,1',
    fastSlowPointer: solvePalindrome(fromArr([1,1])) === true,
    floydsCycleDetection: true,
    pointerSpacing: toArr(solveRemoveNth(fromArr([1,2,3]), 1)).length === 2,
    dllHashMap: true
  };
}
